/**
 * R-2350: Settings → Security log, the browser side. Runs as the signed-in user: the view
 * `security_log` is security_invoker, so RLS shows rows only to the owner of their own company.
 */
"use client";

import { useQuery } from "@tanstack/react-query";
import { createClient } from "@/lib/supabase/client";
import { atRange, SECURITY_LOG_COLUMNS, SECURITY_LOG_LIMIT, type SecurityLogFilter, type SecurityLogRow } from "./log";

/* security_log is newer than database.generated.ts (shared, regenerated by its owner). */
type Loose = { from: (t: string) => any }; // eslint-disable-line @typescript-eslint/no-explicit-any
const db = () => createClient() as unknown as Loose;

export function useSecurityLog(f: SecurityLogFilter, enabled = true) {
  return useQuery({
    queryKey: ["security_log", f.userId, f.recordType, f.from, f.to],
    enabled,
    queryFn: async (): Promise<SecurityLogRow[]> => {
      let q = db().from("security_log").select(SECURITY_LOG_COLUMNS);
      if (f.userId) q = q.eq("user_id", f.userId);
      if (f.recordType) q = q.eq("record_type", f.recordType);
      const r = atRange(f);
      if (r.gte) q = q.gte("at", r.gte);
      if (r.lt) q = q.lt("at", r.lt);
      const { data, error } = await q.order("at", { ascending: false }).limit(SECURITY_LOG_LIMIT);
      if (error) throw new Error(error.message);
      return (data ?? []) as SecurityLogRow[];
    },
  });
}
